CREATE TRIGGER RefCusConditionType_Version_Create
	ON RefCusConditionType
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT ZX2_PK, 'ZX2'
	FROM inserted
GO
CREATE TRIGGER RefCusConditionType_Version_Update
	ON RefCusConditionType
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON ZX2_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
